import app from 'flarum/common/app';
export default class ThreadmarkTypeListState {
  loaded = false;
  all() {
    return app.store.all('threadmark-types');
  }
  load() {
    if (this.loaded) return Promise.resolve(this.all());
    return this.loadingPromise ??= app.store.find('threadmark-types').then(() => {
      this.loaded = true;
      return this.all();
    }).finally(() => {
      this.loadingPromise = undefined;
    });
  }
}
flarum.reg.add('ffans-threadmarks', 'forum/states/ThreadmarkTypeListState', ThreadmarkTypeListState);