import Model from 'flarum/common/Model';
export default class Threadmark extends Model {
  discussion = (() => Model.hasOne('discussion'))();
  post = (() => Model.hasOne('post').call(this))();
  originalPostId = (() => Model.attribute('originalPostId'))();
  originalPostNumber = (() => Model.attribute('originalPostNumber'))();
  type = (() => Model.hasOne('type'))();
  note = (() => Model.attribute('note'))();
  isPostDeleted = (() => Model.attribute('isPostDeleted'))();
  navigationIndex = (() => Model.attribute('navigationIndex'))();
  isPersonal() {
    return this.data.type === 'personal-threadmarks';
  }
  key() {
    return `${this.data.type}-${this.id()}`;
  }
  canEdit() {
    const discussion = this.discussion();
    return this.isPersonal() ? !!this.attribute('canManage') : !!discussion && discussion.canManageThreadmarks();
  }
}
flarum.reg.add('ffans-threadmarks', 'forum/models/Threadmark', Threadmark);